410		// A regular file standing where the temp file's parent directory should
411		// be makes CreateTemp fail with ENOTDIR. The atomic save must surface the
412		// error and leave every other file untouched.
413		blocker := filepath.Join(dir, "blocked")
414		writeRegistry(t, blocker, "x")
415		badPath := filepath.Join(blocker, "registry.json")
