417		reg := &Registry{Version: FormatVersion, Batches: []Batch{{Batch: "B", Product: "P", Quantity: 1, Unit: "kg"}}}
418		if err := Save(badPath, reg); err == nil {
419			t.Fatal("saving through a non-directory path must fail")
420		}
