538	// still name its batch id whenever exactly one "batch" member carries valid,
539	// non-blank text — wherever the "batch" member sits in the object.
540	func TestParseManifestRecordErrorNamesBatch(t *testing.T) {
541		cases := []struct {
542			name      string
543			record    string
544			wantPos   int
545			wantBatch string
546			wantField string // decoded field name the reason must mention
