55	// With no batches, "batches" is written as an empty array, never null, whether
56	// the caller left the slice uninitialized or emptied it, and the file reads
57	// back as a usable empty version-1 registry.
58	func TestSaveEmptyRegistryWritesEmptyArrayAndReadsBack(t *testing.T) {
59		cases := []struct {
60			name    string
61			batches []Batch
62			wantNil bool
63		}{
64			{"uninitialized slice", nil, true},
65			{"already empty slice", []Batch{}, false},
66		}
67		for _, tc := range cases {
68			t.Run(tc.name, func(t *testing.T) {
69				path := filepath.Join(t.TempDir(), "registry.json")
70				reg := &Registry{Version: FormatVersion, Batches: tc.batches}
71				if err := Save(path, reg); err != nil {
72					t.Fatal(err)
73				}
74				data, err := os.ReadFile(path)
75				if err != nil {
76					t.Fatal(err)
77				}
78				if !bytes.Contains(data, []byte(`"batches": []`)) {
79					t.Fatalf("empty registry must serialize batches as [], got %s", data)
80				}
81				if bytes.Contains(data, []byte("null")) {
82					t.Fatalf("empty registry must not contain null: %s", data)
83				}
84				got, existed, err := Load(path)
85				if err != nil || !existed {
86					t.Fatalf("empty registry must read back: existed=%v err=%v", existed, err)
87				}
88				if got.Version != FormatVersion || len(got.Batches) != 0 {
89					t.Fatalf("read-back registry = %+v", got)
90				}
91				// Encoding takes a shallow copy, so the caller's slice header
92				// (nil included) must be left exactly as it was passed in.
93				if (reg.Batches == nil) != tc.wantNil {
94					t.Fatalf("Save mutated the Batches header: nil=%v, want nil=%v", reg.Batches == nil, tc.wantNil)
95				}
96			})
97		}
