131		got, existed, err := Load(path)
132		if err != nil || !existed {
133			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
134		}
135		if got.Version != FormatVersion {
136			t.Fatalf("read-back version = %d, want %d", got.Version, FormatVersion)
137		}
138		assertBatchesEqual(t, got.Batches, want)
139		// The caller's own records survive the save unchanged and in order.
140		assertBatchesEqual(t, reg.Batches, want)
141	}
