1	package batchreg
2	
3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// This file guards the atomicity of Save when the save itself — not the
14	// validation phase and not a neighboring unusable path — fails on the file
15	// being replaced. Two mid-save failure points are covered, each injected
16	// deterministically through the package-level step variables:
17	//
18	//   - the content write into the temporary file stops before the new content
19	//     is complete;
20	//   - the new content is fully prepared on disk, but the final replacement of
21	//     the target file fails.
22	//
23	// In both cases the caller must get an error naming the target path and the
24	// cause, an existing target must keep its exact bytes and modification time
25	// and still load with its original records in order, a missing target must
26	// stay missing, no temporary file may survive, and the caller's submitted
27	// records must be left untouched. A success counterpart with the very same
28	// submission proves the protection is what keeps the old content in place,
29	// not a save that never ran. The injections need no disk fault, no special
30	// filesystem and no missing permissions, so they reproduce offline under any
31	// account, root included.
32	
33	// savedFailureRegistryJSON is the existing registry every failure scenario
34	// starts from: multiple batches, loaded back for comparison in their stored
35	// order.
36	const savedFailureRegistryJSON = `{"version":1,"batches":[` +
37		`{"batch":"OLD-1","product":"苹果","quantity":10,"unit":"kg"},` +
38		`{"batch":"OLD-2","product":"P-2","quantity":20,"unit":"box"},` +
39		`{"batch":"OLD-3","product":"P-3","quantity":30,"unit":"m"}]}`
40	
41	// failedSaveModTime is pinned onto the existing registry file so that any
42	// rewrite — even one restoring identical bytes — is visible as a changed
43	// modification time.
44	var failedSaveModTime = time.Date(2009, time.February, 13, 23, 31, 30, 0, time.UTC)
45	
46	// failureSubmission is a legal batch table under every existing field,
47	// quantity and id rule: the three stored records plus two clearly
48	// distinguishable new ones. It is what the caller hands to Save in every
49	// scenario of this file, failure and success alike.
50	func failureSubmission() []Batch {
51		return []Batch{
52			saveBatch("OLD-1", "苹果", 10, "kg"),
53			saveBatch("OLD-2", "P-2", 20, "box"),
54			saveBatch("OLD-3", "P-3", 30, "m"),
55			saveBatch("NEW-1", "新产品", 99, "箱"),
56			saveBatch("NEW-2", "P-new", MaxQuantity, " pallet "),
57		}
58	}
59	
60	// setupExistingRegistry writes the multi-batch registry, pins its modification
61	// time to failedSaveModTime and returns the target path, the original records
62	// in stored order and the original file bytes.
63	func setupExistingRegistry(t *testing.T) (dir, path string, original []Batch, originalBytes []byte) {
64		t.Helper()
65		dir = t.TempDir()
66		path = filepath.Join(dir, "registry.json")
67		writeRegistry(t, path, savedFailureRegistryJSON)
68		if err := os.Chtimes(path, failedSaveModTime, failedSaveModTime); err != nil {
69			t.Fatal(err)
70		}
71		reg, existed, err := Load(path)
72		if err != nil || !existed {
73			t.Fatalf("fixture registry must load: existed=%v err=%v", existed, err)
74		}
75		original = reg.Batches
76		if len(original) != 3 {
77			t.Fatalf("fixture registry must hold multiple batches, got %+v", original)
78		}
79		originalBytes, err = os.ReadFile(path)
80		if err != nil {
81			t.Fatal(err)
82		}
83		return dir, path, original, originalBytes
