106	// assertExistingTargetUntouched verifies that the failed save behaved as if it
107	// never ran for the actual target: identical bytes, the pinned modification
108	// time, the original records in their original order when read back, no
109	// temporary file left anywhere under dir, and the caller's submitted records
110	// unchanged in content and order.
111	func assertExistingTargetUntouched(t *testing.T, dir, path string, original []Batch, originalBytes []byte, reg *Registry, submitted []Batch) {
112		t.Helper()
113		info, err := os.Stat(path)
114		if err != nil {
115			t.Fatalf("the original registry file must still exist: %v", err)
116		}
117		if !info.ModTime().Equal(failedSaveModTime) {
118			t.Errorf("failed save touched the target's modification time: got %v, want %v", info.ModTime(), failedSaveModTime)
119		}
