121		if err != nil {
122			t.Fatal(err)
123		}
124		if !bytes.Equal(after, originalBytes) {
125			t.Fatalf("failed save changed the target bytes:\nbefore %s\nafter  %s", originalBytes, after)
126		}
127		if bytes.Contains(after, []byte("NEW-")) {
128			t.Fatalf("part of the submitted content landed in the target: %s", after)
129		}
130		loaded, existed, err := Load(path)
131		if err != nil || !existed {
132			t.Fatalf("original registry must still be usable: existed=%v err=%v", existed, err)
133		}
134		assertBatchesEqual(t, loaded.Batches, original)
135		assertNoLeftoverTempFiles(t, dir)
136		assertBatchesEqual(t, reg.Batches, submitted)
137	}
138	
139	// The content write stops halfway through the new content. The save must
140	// abort, clean up its temporary file and leave the existing registry — the
141	// actual replacement target — byte-for-byte and timestamp-for-timestamp
142	// untouched, loading with exactly the original records.
143	func TestSaveWriteFailureKeepsExistingRegistryIntact(t *testing.T) {
144		dir, path, original, originalBytes := setupExistingRegistry(t)
145	
146		cause := errors.New("injected write failure: disk full")
147		writeAttempted := false
148		old := writeTempContent
149		writeTempContent = func(f *os.File, data []byte) (int, error) {
150			writeAttempted = true
