222		reg, existed, err := batchreg.Load(*registryPath)
223		if err != nil {
224			return err
225		}
226		outcome, err := batchreg.Register(reg, batchreg.Input{
227			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
228		})
229		if err != nil {
230			return err
231		}
